package com.capobuf.dubsiren

import android.content.Context
import android.graphics.BlurMaskFilter
import android.graphics.Canvas
import android.graphics.Color
import android.graphics.LinearGradient
import android.graphics.Paint
import android.graphics.Path
import android.graphics.RadialGradient
import android.graphics.RectF
import android.graphics.Shader
import android.graphics.Typeface
import org.json.JSONArray
import org.json.JSONObject

/**
 * Static render of the board front, from assets/pcb_front.json (generated by
 * tools/export_pcb_front.py from hardware/kicad/ESP-DubSiren.kicad_pcb).
 * Drawn once into a software bitmap: soft shadows use BlurMaskFilter.
 * Coordinates are board millimetres; light comes from the top left.
 */
class PcbArt(context: Context) {
    private class Pad(
        val plated: Boolean, val shape: String, val x: Float, val y: Float, val w: Float, val h: Float,
        val rotation: Float, val drillW: Float, val drillH: Float,
    )

    private class Silk(val width: Float, val path: Path)
    private class Label(val x: Float, val y: Float, val size: Float, val rotation: Float, val text: String)

    private val board = Path().apply { fillType = Path.FillType.EVEN_ODD }
    private val pour = Path().apply { fillType = Path.FillType.EVEN_ODD }
    private val tracks = ArrayList<FloatArray>()
    private val vias = ArrayList<FloatArray>()
    private val pads = ArrayList<Pad>()
    private val silk = ArrayList<Silk>()
    private val labels = ArrayList<Label>()

    init {
        val json = JSONObject(context.assets.open("pcb_front.json").bufferedReader().use { it.readText() })
        val outline = json.getJSONArray("outline")
        for (i in 0 until outline.length()) board.addPolyline(outline.getJSONArray(i), close = true)
        val zones = json.getJSONArray("pour")
        for (i in 0 until zones.length()) pour.addPolyline(zones.getJSONArray(i), close = true)
        json.getJSONArray("tracks").forEachArray { tracks.add(it.toFloats()) }
        json.getJSONArray("vias").forEachArray { vias.add(it.toFloats()) }
        json.getJSONArray("pads").forEachArray {
            pads.add(Pad(it.getString(0) != "npth", it.getString(1), it.f(2), it.f(3), it.f(4), it.f(5),
                it.f(6), it.f(7), it.f(8)))
        }
        json.getJSONArray("silk").forEachArray {
            val path = Path()
            val points = JSONArray().apply { for (k in 1 until it.length()) put(it.get(k)) }
            path.addPolyline(points, close = false)
            silk.add(Silk(it.f(0), path))
        }
        json.getJSONArray("texts").forEachArray {
            labels.add(Label(it.f(0), it.f(1), it.f(2), it.f(3), it.getString(5)))
        }
    }

    // ---- Shadow helpers usable for any element baked into the background ----

    private val blur = HashMap<Float, BlurMaskFilter>()

    /** Soft contact shadow of a rounded rectangle, in board mm (canvas already scaled). */
    fun shadowRoundRect(canvas: Canvas, rect: RectF, radius: Float, dx: Float, dy: Float, blurMm: Float,
                        alpha: Int, scale: Float) {
        val paint = shadowPaint(blurMm, alpha, scale)
        rect.offset(dx, dy)
        canvas.drawRoundRect(rect, radius, radius, paint)
        rect.offset(-dx, -dy)
    }

    fun shadowCircle(canvas: Canvas, x: Float, y: Float, r: Float, dx: Float, dy: Float, blurMm: Float,
                     alpha: Int, scale: Float) {
        canvas.drawCircle(x + dx, y + dy, r, shadowPaint(blurMm, alpha, scale))
    }

    private fun shadowPaint(blurMm: Float, alpha: Int, scale: Float) = Paint(Paint.ANTI_ALIAS_FLAG).apply {
        color = Color.argb(alpha, 0, 0, 0)
        // BlurMaskFilter radius is in device pixels.
        maskFilter = blur.getOrPut(blurMm * scale) { BlurMaskFilter(blurMm * scale, BlurMaskFilter.Blur.NORMAL) }
    }

    // ---- Board ----------------------------------------------------------------

    /** Draws the board into [canvas], which is already translated/scaled to board mm. */
    fun drawBoard(canvas: Canvas, scale: Float) {
        val p = Paint(Paint.ANTI_ALIAS_FLAG)

        // Cast shadow on the desk and the 1.6 mm FR4 edge seen from slightly in front.
        canvas.save(); canvas.translate(1.4f, 2.4f)
        canvas.drawPath(board, shadowPaint(3.2f, 170, scale))
        canvas.restore()
        canvas.save(); canvas.translate(0.25f, 0.9f)
        p.color = Color.rgb(0x2E, 0x2C, 0x22) // FR4 core under black mask
        canvas.drawPath(board, p)
        canvas.restore()

        // Black matte soldermask over bare FR4.
        p.shader = LinearGradient(0f, -6f, 86f, 120f, Color.rgb(0x16, 0x18, 0x17), Color.rgb(0x07, 0x08, 0x08),
            Shader.TileMode.CLAMP)
        canvas.drawPath(board, p)
        p.shader = null

        canvas.save()
        canvas.clipPath(board)
        // Copper under the mask: GND pour and tracks read slightly lighter and raised.
        p.color = Color.rgb(0x1A, 0x1E, 0x1C)
        canvas.drawPath(pour, p)
        val line = Paint(Paint.ANTI_ALIAS_FLAG).apply {
            style = Paint.Style.STROKE
            strokeCap = Paint.Cap.ROUND
        }
        for ((pass, color, dx, dy) in listOf(
            Quad(0, Color.rgb(0x05, 0x06, 0x06), 0.06f, 0.08f),
            Quad(1, Color.rgb(0x26, 0x2C, 0x29), -0.04f, -0.05f),
            Quad(2, Color.rgb(0x1D, 0x22, 0x20), 0f, 0f),
        )) {
            line.color = color
            for (t in tracks) {
                line.strokeWidth = t[0] + if (pass == 2) -0.02f else 0f
                canvas.drawLine(t[1] + dx, t[2] + dy, t[3] + dx, t[4] + dy, line)
            }
        }
        // Tented vias: small domes under the mask.
        for (v in vias) {
            val r = v[2] / 2
            p.shader = RadialGradient(v[0] - r * 0.35f, v[1] - r * 0.35f, r * 1.3f,
                Color.rgb(0x33, 0x3A, 0x36), Color.rgb(0x10, 0x12, 0x11), Shader.TileMode.CLAMP)
            canvas.drawCircle(v[0], v[1], r, p)
        }
        p.shader = null
        // Gloss of the mask.
        p.shader = LinearGradient(0f, -6f, 60f, 70f, Color.argb(26, 255, 255, 255), Color.argb(0, 255, 255, 255),
            Shader.TileMode.CLAMP)
        canvas.drawRect(0f, -6f, 86f, 120f, p)
        p.shader = null
        canvas.restore()

        drawPads(canvas)
        drawSilk(canvas, scale)
    }

    private fun drawPads(canvas: Canvas) {
        val gold = Paint(Paint.ANTI_ALIAS_FLAG)
        val hole = Paint(Paint.ANTI_ALIAS_FLAG)
        val rect = RectF()
        for (pad in pads) {
            canvas.save()
            canvas.translate(pad.x, pad.y)
            canvas.rotate(-pad.rotation)
            if (pad.plated) {
                // ENIG: warm gold, lit from the top left.
                gold.shader = LinearGradient(-pad.w / 2, -pad.h / 2, pad.w / 2, pad.h / 2,
                    Color.rgb(0xF2, 0xD6, 0x8E), Color.rgb(0x9C, 0x76, 0x34), Shader.TileMode.CLAMP)
                rect.set(-pad.w / 2, -pad.h / 2, pad.w / 2, pad.h / 2)
                val r = when (pad.shape) {
                    "circle", "oval" -> minOf(pad.w, pad.h) / 2
                    "roundrect" -> minOf(pad.w, pad.h) * 0.25f
                    else -> 0f
                }
                canvas.drawRoundRect(rect, r, r, gold)
            }
            if (pad.drillW > 0f) {
                // Through hole: the dark inside of the barrel, deeper towards the bottom right.
                rect.set(-pad.drillW / 2, -pad.drillH / 2, pad.drillW / 2, pad.drillH / 2)
                hole.shader = RadialGradient(-pad.drillW * 0.15f, -pad.drillH * 0.15f,
                    maxOf(pad.drillW, pad.drillH) * 0.6f,
                    if (pad.plated) Color.rgb(0x3A, 0x2E, 0x18) else Color.rgb(0x1A, 0x1B, 0x1C),
                    Color.rgb(0x02, 0x02, 0x02), Shader.TileMode.CLAMP)
                val r = minOf(pad.drillW, pad.drillH) / 2
                canvas.drawRoundRect(rect, r, r, hole)
            }
            canvas.restore()
        }
    }

    private fun drawSilk(canvas: Canvas, scale: Float) {
        val ink = Paint(Paint.ANTI_ALIAS_FLAG).apply {
            style = Paint.Style.STROKE
            strokeCap = Paint.Cap.ROUND
            strokeJoin = Paint.Join.ROUND
            color = Color.rgb(0xE4, 0xE4, 0xDE)
        }
        for (s in silk) {
            ink.strokeWidth = s.width
            canvas.drawPath(s.path, ink)
        }
        // Text drawn in pixels: tiny text sizes on a scaled canvas render poorly.
        val text = Paint(Paint.ANTI_ALIAS_FLAG).apply {
            color = ink.color
            textAlign = Paint.Align.CENTER
            typeface = Typeface.create("sans-serif-condensed", Typeface.BOLD)
        }
        for (label in labels) {
            canvas.save()
            canvas.translate(label.x, label.y)
            canvas.rotate(-label.rotation)
            canvas.scale(1f / scale, 1f / scale)
            text.textSize = label.size / 0.72f * scale // KiCad size ~ cap height
            canvas.drawText(label.text, 0f, label.size * scale / 2f, text)
            canvas.restore()
        }
    }

    private data class Quad(val pass: Int, val color: Int, val dx: Float, val dy: Float)
}

private fun Path.addPolyline(points: JSONArray, close: Boolean) {
    if (points.length() < 4) return
    moveTo(points.getDouble(0).toFloat(), points.getDouble(1).toFloat())
    var i = 2
    while (i + 1 < points.length()) {
        lineTo(points.getDouble(i).toFloat(), points.getDouble(i + 1).toFloat())
        i += 2
    }
    if (close) close()
}

private inline fun JSONArray.forEachArray(action: (JSONArray) -> Unit) {
    for (i in 0 until length()) action(getJSONArray(i))
}

private fun JSONArray.toFloats() = FloatArray(length()) { getDouble(it).toFloat() }
private fun JSONArray.f(index: Int) = getDouble(index).toFloat()
